import asyncio
import csv
import os

async def act(page):
    # Call the provided function to export customers to CSV
    await export_customers_to_csv(page)

    # Wait for download to complete
    await asyncio.sleep(5)

    # Try to find the downloaded CSV file
    # Assuming it's in the current working directory or default downloads
    downloads_path = os.path.join(os.getcwd(), 'downloads')
    if not os.path.exists(downloads_path):
        downloads_path = os.getcwd()  # Fallback to current directory

    csv_files = [f for f in os.listdir(downloads_path) if f.endswith('.csv')] if os.path.exists(downloads_path) else []
    if not csv_files:
        # If no CSV found, check the default downloads folder
        home_path = os.path.expanduser('~')
        downloads_path = os.path.join(home_path, 'Downloads')
        csv_files = [f for f in os.listdir(downloads_path) if f.endswith('.csv')] if os.path.exists(downloads_path) else []

    if not csv_files:
        return "No CSV file found after export."

    # Get the most recent CSV file
    latest_file = max(csv_files, key=lambda f: os.path.getmtime(os.path.join(downloads_path, f)))
    file_path = os.path.join(downloads_path, latest_file)

    # Read and parse the CSV
    try:
        with open(file_path, 'r', newline='', encoding='utf-8') as file:
            reader = csv.DictReader(file)
            rows = list(reader)

            if not rows:
                return "CSV file is empty."

            # Find the column for cancellations; assume it's named 'cancellations' or similar
            # We need to identify the correct column name
            cancellation_col = None
            if reader.fieldnames:
                for col in reader.fieldnames:
                    if 'cancel' in col.lower():
                        cancellation_col = col
                        break

            if not cancellation_col and reader.fieldnames:
                # If no cancellation column, check for other possible names
                for col in reader.fieldnames:
                    if 'order' in col.lower() and 'cancel' in col.lower():
                        cancellation_col = col
                        break
                if not cancellation_col:
                    return "No cancellation column found in CSV."
            else:
                return "No fieldnames in CSV."

            # Find the row with the maximum cancellations
            max_cancellations = -1
            target_row = None
            for row in rows:
                try:
                    cancellations = int(row.get(cancellation_col, 0))
                except (ValueError, TypeError):
                    cancellations = 0
                if cancellations > max_cancellations:
                    max_cancellations = cancellations
                    target_row = row

            if not target_row:
                return "No customer with cancellations found."

            # Extract email, name, and phone number
            # Assume columns are named 'email', 'name', 'phone' or similar
            email = target_row.get('email', '')
            name = target_row.get('name', '')
            phone = target_row.get('phone', '')

            # If columns have different names, try to find them
            if not email and reader.fieldnames:
                for col in reader.fieldnames:
                    if 'email' in col.lower():
                        email = target_row.get(col, '')
                        break
            if not name and reader.fieldnames:
                for col in reader.fieldnames:
                    if 'name' in col.lower():
                        name = target_row.get(col, '')
                        break
            if not phone and reader.fieldnames:
                for col in reader.fieldnames:
                    if 'phone' in col.lower():
                        phone = target_row.get(col, '')
                        break

            result = f"Email: {email}, Name: {name}, Phone: {phone}"
            return result
    except Exception as e:
        return f"Error processing CSV: {str(e)}"

